UPDATE cw_outbox_message
SET `status` = 'PROCESSING', lease_owner = #{owner}, lease_until_ms = #{leaseUntilMs}
WHERE id = #{id}
  AND ((`status` = 'PENDING' AND next_attempt_at_ms <= #{nowMs})
    OR (`status` = 'PROCESSING' AND lease_until_ms <= #{nowMs}))

mapper.select:
SELECT  FROM cw_outbox_message
WHERE `status` = 'PROCESSING' AND lease_owner = #{owner} AND lease_until_ms = #{leaseUntilMs}
ORDER BY next_attempt_at_ms, created_at_ms

mapper.update:
UPDATE cw_outbox_message
SET `status` = #{record.status}, attempts = #{record.attempts},
    next_attempt_at_ms = #{record.nextAttemptAtMs}, lease_owner = #{record.leaseOwner},
    lease_until_ms = #{record.leaseUntilMs}, last_error = #{record.lastError},
    finished_at_ms = #{record.finishedAtMs}
WHERE id = #{record.id} AND `status` = 'PROCESSING' AND lease_owner = #{owner}
